const slides = [...document.querySelectorAll('.slide')];
function currentIndex() {
  const y = window.scrollY;
  let closest = 0;
  let min = Infinity;
  slides.forEach((slide, index) => {
    const distance = Math.abs(slide.offsetTop - y);
    if (distance < min) { min = distance; closest = index; }
  });
  return closest;
}
function go(delta) {
  const target = Math.max(0, Math.min(slides.length - 1, currentIndex() + delta));
  slides[target].scrollIntoView({ behavior: 'smooth' });
}
document.addEventListener('keydown', (event) => {
  if (['ArrowRight', 'PageDown', ' '].includes(event.key)) { event.preventDefault(); go(1); }
  if (['ArrowLeft', 'PageUp'].includes(event.key)) { event.preventDefault(); go(-1); }
});
</script>
