#!/usr/bin/env python3
import http.server
import json
import subprocess
import tempfile
import threading
from pathlib import Path
from pptx import Presentation
from pptx.util import Emu

html_path = Path('/app/work/deck.html').resolve()
out_pptx = Path('/app/output/final_deck.pptx').resolve()
width, height = 1920, 1080

class QuietHandler(http.server.SimpleHTTPRequestHandler):
    def log_message(self, format, *args):
        pass

server = http.server.HTTPServer(('127.0.0.1', 0), lambda *a, **kw: QuietHandler(*a, directory=str(html_path.parent), **kw))
threading.Thread(target=server.serve_forever, daemon=True).start()
url = f'http://127.0.0.1:{server.server_address[1]}/{html_path.name}'

with tempfile.TemporaryDirectory(prefix='slides_all_') as tmp:
    tmp_path = Path(tmp)
    script = tmp_path / 'capture.cjs'
    script.write_text(f"""
const {{ chromium }} = require('playwright');
(async () => {{
  const browser = await chromium.launch({{ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || undefined }});
  const page = await browser.newPage();
  await page.setViewportSize({{ width: {width}, height: {height} }});
  await page.goto('{url}', {{ waitUntil: 'networkidle' }});
  const slideCount = await page.$$eval('.slide', els => els.length);
  for (let i = 0; i < slideCount; i++) {{
    await page.evaluate((idx) => showSlide(idx), i);
    await page.waitForTimeout(250);
    const name = String(i + 1).padStart(3, '0');
    await page.screenshot({{ path: `{tmp}/slide_${{name}}.png`, fullPage: false }});
  }}
  console.log(JSON.stringify({{ captured: slideCount }}));
  await browser.close();
}})();
""")
    result = subprocess.run(['node', str(script)], cwd=str(html_path.parent), text=True, capture_output=True, env={**__import__('os').environ, 'PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH': '/root/.cache/ms-playwright/chromium_headless_shell-1155/chrome-linux/headless_shell'})
    if result.returncode != 0:
        print(result.stdout)
        print(result.stderr)
        raise SystemExit(result.returncode)
    print(result.stdout.strip())
    images = sorted(tmp_path.glob('slide_*.png'))
    prs = Presentation()
    prs.slide_width = Emu(12192000)
    prs.slide_height = Emu(6858000)
    blank = prs.slide_layouts[6]
    for image in images:
        slide = prs.slides.add_slide(blank)
        slide.shapes.add_picture(str(image), 0, 0, width=prs.slide_width, height=prs.slide_height)
    out_pptx.parent.mkdir(parents=True, exist_ok=True)
    prs.save(str(out_pptx))
    print(f'Saved {len(images)} slides to {out_pptx}')
server.shutdown()
